b=1;
draw=a=>{
	if(b){createCanvas(w=600,w);
	background(15);}
	stroke(255),
	n=12;
	for(i=0;i<n;i++)
		for(j=0;j<10;j++)
			a=random(Math.PI*2),
			r=map(i,0,n-1,w/3,w/10)*pow(random(),map(i,0,n-1,0.1,0.2)-abs(a-Math.PI)/10),
			point(cos(a)*(r)+w/2,sin(a)*r+w/2);
